class Solution {
  public int distinctPoints(String s, int k) {
    int n = s.length();
    int[] px = new int[n + 1], py = new int[n + 1];
    for (int i = 0; i < n; i++) {
      char c = s.charAt(i);
      px[i + 1] = px[i] + (c == 'R' ? 1 : c == 'L' ? -1 : 0);
      py[i + 1] = py[i] + (c == 'U' ? 1 : c == 'D' ? -1 : 0);
    }
    java.util.HashSet<Long> seen = new java.util.HashSet<>();
    for (int i = 0; i + k <= n; i++) {
      long x = px[n] - (px[i + k] - px[i]), y = py[n] - (py[i + k] - py[i]);
      seen.add((x + 200_000) * 1_000_000L + (y + 200_000));
    }
    return seen.size();
  }
}
